 "content": "from collections import deque


def transform(grid):
    """Drop monochromatic 4-connected objects toward a solid color-2 bar."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    if all(v == 2 for v in g[0]):
        direction = 1  # separator is below the objects; gravity is downward
        barrier = 0
    elif all(v == 2 for v in g[-1]):
        direction = -1  # separator is above the objects; gravity is upward
        barrier = h - 1
    else:
        raise ValueError("expected a solid color-2 boundary row")

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append((color, cells))

    # Simulate one-cell gravity steps for all objects until none can move.
    positions = [list(cells) for _, cells in objects]
    colors = [color for color, _ in objects]
    while True:
        occupied = {cell: i for i, cells in enumerate(positions) for cell in cells}
        movable = []
        for i, cells in enumerate(positions):
            shifted = [(r + direction, c) for r, c in cells]
            can_move = all(0 <= r < h and 0 <= c < w and g[r][c] != 2 and (r, c) not in occupied
                           for r, c in shifted)
            movable.append(can_move)
        if not any(movable):
            break
        for i, can_move in enumerate(movable):
            if can_move:
                positions[i] = [(r + direction, c) for r, c in positions[i]]

    out = [[0] * w for _ in range(h)]
    for i, cells in enumerate(positions):
        for r, c in cells:
            out[r][c] = colors[i]
    for c in range(w):
        out[barrier][c] = 2
    return out


